/* SKYDOMINION · етап 7.63 · лист спрайтів вибуху: 8 стовпців × 7 рядів, 52 кадри по 128 px, прозорий фон (assets/boom_sheet.webp).
   Це ДВІ окремі послідовності: a = кадри 0–19 (спалах → куля → щільний темний дим; без згасання), b = кадри 20–51 (яскрава куля → бурий пил → сірий дим, що розсіюється повністю) */
(function(){
  const B = window.BV_BOOM = { cols: 8, cell: 128, n: 52, seq: { a: [0, 19], b: [20, 51] }, img: null, ready: false,
    src: "data:image/webp;base64," };
  const im = new Image(); im.onload = () => { B.img = im; B.ready = true; }; im.src = B.src;
})();
